<?php
require_once __DIR__ . '/includes_excel_data.php';
ensureExcelTables($pdo);
$defaultFY = latest_excel_fiscal_year($pdo);
$fy = (int)($_GET['fy'] ?? $defaultFY);
if ($fy < 2500 || $fy > 2700) $fy = $defaultFY;
$month = (int)($_GET['month'] ?? 0);
$section = (string)($_GET['section'] ?? 'all');
if (!in_array($section, ['all','ap','online','booth','unknown'], true)) $section = 'all';
$where = ["(CAST(NULLIF(REPLACE(COALESCE(`ส่วนลด`,''),',',''),'') AS DECIMAL(14,2)) > 0 OR CAST(NULLIF(REPLACE(COALESCE(`บัตรกำนัล`,''),',',''),'') AS DECIMAL(14,2)) > 0)"];
$params = [];
$where[] = 'fiscal_year=?'; $params[] = $fy;
if ($month >= 1 && $month <= 12) { $where[] = "COALESCE(MONTH(STR_TO_DATE(SUBSTRING_INDEX(TRIM(`วันที่สมัคร`),' ',1),'%d/%m/%Y')),MONTH(STR_TO_DATE(SUBSTRING_INDEX(TRIM(`วันที่สมัคร`),' ',1),'%Y-%m-%d')))=?"; $params[] = $month; }
if ($section !== 'all') { $where[] = 'source_section=?'; $params[] = $section; }
$whereSql = implode(' AND ', $where);
$sumSql = "SELECT COUNT(*) items, COALESCE(SUM(CAST(NULLIF(REPLACE(COALESCE(`จำนวนเงินทั้งหมด`,''),',',''),'') AS DECIMAL(14,2))),0) before_amount, COALESCE(SUM(CAST(NULLIF(REPLACE(COALESCE(`ส่วนลด`,''),',',''),'') AS DECIMAL(14,2))),0) discount_amount, COALESCE(SUM(CAST(NULLIF(REPLACE(COALESCE(`บัตรกำนัล`,''),',',''),'') AS DECIMAL(14,2))),0) voucher_amount, COALESCE(SUM(CAST(NULLIF(REPLACE(COALESCE(`ยอดสุทธิ`,''),',',''),'') AS DECIMAL(14,2))),0) net_amount FROM excel_member_records WHERE $whereSql";
$st=$pdo->prepare($sumSql);$st->execute($params);$sum=$st->fetch(PDO::FETCH_ASSOC);
$groupSql = "SELECT COALESCE(NULLIF(`กิจกรรม/ Package`,''),'ไม่ระบุ Package') package_name, COUNT(*) items, COALESCE(SUM(CAST(NULLIF(REPLACE(COALESCE(`ส่วนลด`,''),',',''),'') AS DECIMAL(14,2))),0) discount_amount, COALESCE(SUM(CAST(NULLIF(REPLACE(COALESCE(`บัตรกำนัล`,''),',',''),'') AS DECIMAL(14,2))),0) voucher_amount, COALESCE(SUM(CAST(NULLIF(REPLACE(COALESCE(`ยอดสุทธิ`,''),',',''),'') AS DECIMAL(14,2))),0) net_amount FROM excel_member_records WHERE $whereSql GROUP BY package_name ORDER BY discount_amount DESC LIMIT 50";
$st=$pdo->prepare($groupSql);$st->execute($params);$packages=$st->fetchAll(PDO::FETCH_ASSOC);
$listSql = "SELECT `วันที่สมัคร`,`หมายเลขสมาชิก`,`รายชื่อลูกค้า`,`กิจกรรม/ Package`,`ประเภทการสมัคร`,`ช่องทางจำหน่าย`,`จำนวนเงินทั้งหมด`,`ส่วนลด`,`บัตรกำนัล`,`ยอดจ่าย`,`ยอดสุทธิ`,`สถานะรายการ`,`หมายเหตุ`,`source_section` FROM excel_member_records WHERE $whereSql ORDER BY id DESC LIMIT 200";
$st=$pdo->prepare($listSql);$st->execute($params);$records=$st->fetchAll(PDO::FETCH_ASSOC);
$months=[10=>'ต.ค.',11=>'พ.ย.',12=>'ธ.ค.',1=>'ม.ค.',2=>'ก.พ.',3=>'มี.ค.',4=>'เม.ย.',5=>'พ.ค.',6=>'มิ.ย.',7=>'ก.ค.',8=>'ส.ค.',9=>'ก.ย.'];$chartLabels=array_values($months);$chartDiscount=array_fill(0,12,0);$chartNet=array_fill(0,12,0);
if($fy>=2500&&$fy<=2700){$chartSql="SELECT COALESCE(MONTH(STR_TO_DATE(SUBSTRING_INDEX(TRIM(`วันที่สมัคร`),' ',1),'%d/%m/%Y')),MONTH(STR_TO_DATE(SUBSTRING_INDEX(TRIM(`วันที่สมัคร`),' ',1),'%Y-%m-%d'))) m, COALESCE(SUM(CAST(NULLIF(REPLACE(COALESCE(`ส่วนลด`,''),',',''),'') AS DECIMAL(14,2))),0) discount_amount, COALESCE(SUM(CAST(NULLIF(REPLACE(COALESCE(`ยอดสุทธิ`,''),',',''),'') AS DECIMAL(14,2))),0) net_amount FROM excel_member_records WHERE fiscal_year=? AND (CAST(NULLIF(REPLACE(COALESCE(`ส่วนลด`,''),',',''),'') AS DECIMAL(14,2)) > 0 OR CAST(NULLIF(REPLACE(COALESCE(`บัตรกำนัล`,''),',',''),'') AS DECIMAL(14,2)) > 0)"; $chartParams=[$fy];if($section!=='all'){$chartSql.=' AND source_section=?';$chartParams[]=$section;}$chartSql.=' GROUP BY m';$cs=$pdo->prepare($chartSql);$cs->execute($chartParams);$byMonth=[];foreach($cs->fetchAll(PDO::FETCH_ASSOC) as $r)$byMonth[(int)$r['m']]=$r;foreach(array_keys($months) as $i=>$m){$r=$byMonth[$m]??[];$chartDiscount[$i]=(float)($r['discount_amount']??0);$chartNet[$i]=(float)($r['net_amount']??0);}}
$labels=['ap'=>'สมัครที่ อพ.','online'=>'สมัครออนไลน์','booth'=>'ออกบูธ','unknown'=>'ยังไม่จัดหมวด'];
?>
<!doctype html><html lang="th"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>โปรโมชั่น / ส่วนลดประจำเดือน | NSM Member Club</title><link rel="stylesheet" href="assets/css/style.css?v=10"></head><body>
<?php $activePage = basename($_SERVER['SCRIPT_NAME'] ?? 'monthly_promotions.php'); require __DIR__ . '/includes/navigation.php'; ?>
<main class="main"><div class="topbar"><div><h1>โปรโมชั่น / ส่วนลดประจำเดือน</h1><p>แสดงรายการที่มีส่วนลดหรือบัตรกำนัลจากข้อมูล Excel โดยไม่เหมารวมทุก Package ว่าเป็นโปรโมชั่น</p></div></div><div class="content">
<div class="card"><form method="get" style="display:flex;gap:12px;align-items:end;flex-wrap:wrap"><div><div class="filter-label">ปีงบประมาณ</div><input class="form-control" type="number" name="fy" value="<?=e($fy)?>" style="width:130px"></div><div><div class="filter-label">เดือน</div><select class="form-control" name="month"><option value="0">ทั้งหมด</option><?php foreach($months as $m=>$label):?><option value="<?=$m?>" <?=$month===$m?'selected':''?>><?=e($label)?></option><?php endforeach;?></select></div><div><div class="filter-label">หมวดสมาชิก</div><select class="form-control" name="section"><option value="all" <?=$section==='all'?'selected':''?>>ทุกหมวด</option><?php foreach($labels as $k=>$label):?><option value="<?=e($k)?>" <?=$section===$k?'selected':''?>><?=e($label)?></option><?php endforeach;?></select></div><button class="btn btn-primary" type="submit">แสดงผล</button></form></div>
<div class="summary-note" style="background:#f8fafc;border:1px solid #e7edf3;padding:14px 16px;border-radius:12px;color:#526174;margin-bottom:18px">หน้านี้นับเฉพาะรายการที่มีค่าในช่องส่วนลดหรือบัตรกำนัลมากกว่า 0 เท่านั้น รายงานใช้ “จำนวนเงินทั้งหมด” เป็นยอดก่อนลดตามชื่อคอลัมน์ และแสดง “ยอดสุทธิ” แยกไว้โดยยังไม่ยืนยันว่าเป็นนิยามรายได้หลักของบริษัท</div>
<div class="stats"><div class="stat-card"><div><div class="stat-label">รายการที่มีส่วนลด/บัตรกำนัล</div><div class="stat-number"><?=number_format((int)$sum['items'])?></div></div><div class="stat-icon blue">📄</div></div><div class="stat-card"><div><div class="stat-label">ยอดก่อนลด</div><div class="stat-number">฿<?=number_format((float)$sum['before_amount'],2)?></div></div><div class="stat-icon green">💵</div></div><div class="stat-card"><div><div class="stat-label">ส่วนลดรวม</div><div class="stat-number">฿<?=number_format((float)$sum['discount_amount'],2)?></div></div><div class="stat-icon orange">🏷️</div></div><div class="stat-card"><div><div class="stat-label">บัตรกำนัล</div><div class="stat-number">฿<?=number_format((float)$sum['voucher_amount'],2)?></div></div><div class="stat-icon purple">🎟️</div></div></div>
<div class="grid" style="margin-bottom:20px"><div class="card"><div class="card-header"><div><div class="card-title">ส่วนลดรายเดือน</div><div class="card-subtitle">ปีงบประมาณ <?=e($fy)?></div></div></div><div class="chart-container"><canvas id="discountChart"></canvas></div></div><div class="card"><div class="card-header"><div><div class="card-title">ยอดสุทธิรายเดือน</div><div class="card-subtitle">แสดงเพื่อเปรียบเทียบ ไม่ได้กำหนดเป็นสูตรรายได้หลัก</div></div></div><div class="chart-container"><canvas id="netChart"></canvas></div></div></div>
<div class="card"><div class="card-title">แยกตาม Package / กิจกรรมที่มีส่วนลดหรือบัตรกำนัล</div><div style="overflow:auto"><table class="building-table"><thead><tr><th>Package / กิจกรรม</th><th class="right">รายการ</th><th class="right">ส่วนลด</th><th class="right">บัตรกำนัล</th><th class="right">ยอดสุทธิ</th></tr></thead><tbody><?php foreach($packages as $r):?><tr><td><?=e($r['package_name'])?></td><td class="right"><?=number_format((int)$r['items'])?></td><td class="right">฿<?=number_format((float)$r['discount_amount'],2)?></td><td class="right">฿<?=number_format((float)$r['voucher_amount'],2)?></td><td class="right">฿<?=number_format((float)$r['net_amount'],2)?></td></tr><?php endforeach;?></tbody></table></div></div>
<div class="card"><div class="card-title">รายการต้นทางจาก Excel</div><div style="overflow:auto"><table class="building-table"><thead><tr><th>วันที่</th><th>สมาชิก</th><th>หมวด</th><th>Package / กิจกรรม</th><th>ยอดก่อนลด</th><th>ส่วนลด</th><th>บัตรกำนัล</th><th>ยอดจ่าย</th><th>ยอดสุทธิ</th><th>สถานะ</th></tr></thead><tbody><?php foreach($records as $r):?><tr><td><?=e($r['วันที่สมัคร'])?></td><td><?=e($r['หมายเลขสมาชิก'])?><br><?=e($r['รายชื่อลูกค้า'])?></td><td><?=e($labels[$r['source_section']]??$r['source_section'])?></td><td><?=e($r['กิจกรรม/ Package'])?></td><td>฿<?=number_format((float)str_replace(',','',$r['จำนวนเงินทั้งหมด']),2)?></td><td>฿<?=number_format((float)str_replace(',','',$r['ส่วนลด']),2)?></td><td>฿<?=number_format((float)str_replace(',','',$r['บัตรกำนัล']),2)?></td><td>฿<?=number_format((float)str_replace(',','',$r['ยอดจ่าย']),2)?></td><td>฿<?=number_format((float)str_replace(',','',$r['ยอดสุทธิ']),2)?></td><td><?=e($r['สถานะรายการ'])?></td></tr><?php endforeach;?></tbody></table></div></div>
</div></main><script src="https://cdn.jsdelivr.net/npm/chart.js"></script><script>const labels=<?=json_encode($chartLabels,JSON_UNESCAPED_UNICODE)?>,discount=<?=json_encode($chartDiscount)?>,net=<?=json_encode($chartNet)?>;const dc=document.getElementById('discountChart');if(dc&&typeof Chart!=='undefined')new Chart(dc,{type:'bar',data:{labels,datasets:[{label:'ส่วนลด',data:discount,borderWidth:1}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'bottom'},tooltip:{callbacks:{label:c=>'฿'+Number(c.raw||0).toLocaleString('th-TH')}}},scales:{y:{beginAtZero:true,ticks:{callback:v=>'฿'+Number(v).toLocaleString('th-TH')}}}}});const nc=document.getElementById('netChart');if(nc&&typeof Chart!=='undefined')new Chart(nc,{type:'line',data:{labels,datasets:[{label:'ยอดสุทธิ',data:net,borderWidth:2,tension:.25,fill:false}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'bottom'},tooltip:{callbacks:{label:c=>'฿'+Number(c.raw||0).toLocaleString('th-TH')}}},scales:{y:{beginAtZero:true,ticks:{callback:v=>'฿'+Number(v).toLocaleString('th-TH')}}}}});</script></body></html>
